/**
 * Unit tests for CategoryPlot.removeRangeMarker.
 */
public class CategoryPlot_removeRangeMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker marker;
    private Map<Integer, ArrayList<Marker>> foregroundMarkersMap;
    private Map<Integer, ArrayList<Marker>> backgroundMarkersMap;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        marker = mock(Marker.class);

        // Use reflection to access private fields foregroundRangeMarkers and backgroundRangeMarkers
        // to setup the internal state for testing.
        foregroundMarkersMap = new HashMap<>();
        backgroundMarkersMap = new HashMap<>();

        setPrivateField(plot, "foregroundRangeMarkers", foregroundMarkersMap);
        setPrivateField(plot, "backgroundRangeMarkers", backgroundMarkersMap);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveRangeMarker_NullMarker_ThrowsException() {
        plot.removeRangeMarker(0, null, Layer.FOREGROUND, true);
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Success_WithNotify() {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        foregroundMarkersMap.put(index, markers);

        // Note: fireChangeEvent is internal. We verify return value.
        // In a real JFreeChart environment, we might use a ChangeEventListener.
        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue("List should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_Foreground_Fail_NoNotify() {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        Marker otherMarker = mock(Marker.class);
        markers.add(otherMarker);
        foregroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, true);

        assertFalse("Marker should not be removed", result);
        assertEquals(1, markers.size());
    }

    @Test
    public void testRemoveRangeMarker_Background_Success_WithNotify() {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        backgroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.BACKGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue(markers.isEmpty());
    }

    @Test
    public void testRemoveRangeMarker_Background_Fail_NoNotify() {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        Marker otherMarker = mock(Marker.class);
        markers.add(otherMarker);
        backgroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.BACKGROUND, true);

        assertFalse("Marker should not be removed", result);
        assertEquals(1, markers.size());
    }

    @Test
    public void testRemoveRangeMarker_NotifyFalse_DoesNotTriggerLogic() {
        // Testing the branch where removed is true but notify is false
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(marker);
        foregroundMarkersMap.put(index, markers);

        boolean result = plot.removeRangeMarker(index, marker, Layer.FOREGROUND, false);

        assertTrue("Marker should be removed", result);
        assertTrue(markers.isEmpty());
    }
}
